Object.assign(FD,DM(`Privilegio di sottoclasse:Ottieni un privilegio dalla tua sottoclasse (vedi la descrizione della sottoclasse);Aumento dei punteggi:+2 a una caratteristica, +1 a due oppure un talento (massimo 20);Dono epico:Ottieni un Dono epico, un talento di livello epico;Istinto feroce:Vantaggio ai tiri di iniziativa;Balzo istintivo:Con l'azione bonus per entrare in Ira ti muovi fino a metà velocità;Colpo brutale:Rinunci al vantaggio di Attacco sconsiderato per 1d10 danni extra e un effetto;Ira implacabile:A 0 PF in Ira fai un TS COS (CD 10, +5 a ogni uso) per restare a PF pari al doppio del livello;Colpo brutale migliorato:Nuovi effetti di Colpo brutale (Colpo barcollante e Colpo spezzante);Ira persistente:Recuperi tutte le Ire quando tiri iniziativa e l'Ira non finisce presto;Colpo brutale superiore:Danni extra 2d10 e due effetti insieme;Forza indomabile:Prove e TS di FOR hanno come minimo il tuo punteggio di FOR;Campione primordiale:FOR e COS aumentano di 4 (massimo 25);Contraffascinazione:Reazione che dà vantaggio ai TS contro charme e paura a te e agli alleati vicini;Segreti magici:Impari incantesimi dalle liste di Bardo, Chierico, Druido e Mago;Ispirazione superiore:Quando tiri iniziativa recuperi Ispirazione bardica fino a due usi;Parole di creazione:Hai sempre preparati Parola del Potere Guarire e Parola del Potere Uccidere e puoi colpire un secondo bersaglio entro 3 m dal primo;Colpi benedetti:Scegli Colpo divino (una volta per turno con un'arma 1d8 danni necrotici o radianti extra) oppure Incantesimi potenti (aggiungi SAG ai danni dei trucchetti da Chierico);Intervento divino:Una volta per riposo lungo lanci un incantesimo da Chierico di livello 5 o inferiore senza slot;Colpi benedetti migliorati:Il Colpo divino sale a 2d8; gli Incantesimi potenti danno PF temporanei pari a due volte SAG a una creatura entro 18 m;Intervento divino superiore:Puoi usare Intervento divino per lanciare Desiderio;Furia elementale:Scegli Colpo primordiale (una volta per turno 1d8 danni da freddo, fuoco, fulmine o tuono con un'arma o un attacco in forma di bestia) oppure Incantesimi potenti (SAG ai danni dei trucchetti da Druido);Furia elementale migliorata:Il Colpo primordiale sale a 2d8 oppure i trucchetti da Druido con gittata di 3 m o più guadagnano 90 m di gittata;Incantesimi bestiali:Lanci incantesimi mentre sei in Forma selvatica;Arcidruido:Recuperi Forma selvatica quando tiri iniziativa e ignori le componenti verbali e somatiche;Spostamento tattico:Quando usi Recuperare energie ti muovi fino a metà velocità senza provocare attacchi di opportunità;Maestro tattico:Con un'arma di cui usi la maestria puoi sostituire la proprietà con Spingere, Fiaccare o Rallentare;Indomito:Ripeti un TS fallito aggiungendo il tuo livello da Guerriero (usi limitati);Due attacchi extra:Attacchi tre volte con l'azione Attacco;Attacchi studiati:Dopo aver mancato un bersaglio hai vantaggio contro di lui al tuo prossimo attacco;Impeto di azione migliorato:Puoi usare due volte Impeto di azione tra riposi (non nello stesso turno);Tre attacchi extra:Attacchi quattro volte con l'azione Attacco;Colpi potenziati:I colpi senza armi possono infliggere danni di forza;Elusione:Con un TS DES riuscito subisci 0 danni, con un fallimento la metà;Movimento acrobatico:Ti muovi su pareti e liquidi durante il movimento;Concentrazione migliorata:Potenzi Raffica di colpi, Difesa paziente e Passo del vento;Autoguarigione:Alla fine del turno rimuovi affascinato, spaventato o avvelenato;Deviare energia:Deviare proiettili protegge da ogni tipo di danno;Sopravvissuto disciplinato:Competenza in tutti i TS e rilancio dei TS con Ferocia;Concentrazione perfetta:A iniziativa recuperi Ferocia fino a 4 punti se ne hai meno;Difesa superiore:Spendendo Ferocia resisti a ogni danno tranne la forza;Corpo e mente:DES e SAG aumentano di 4 (massimo 25);Aura di protezione:Tu e gli alleati entro 3 m aggiungete il modificatore di CAR ai TS;Scacciare nemici:Con Incanalare Divinità spaventi i nemici vicini (TS SAG);Aura di coraggio:Tu e gli alleati entro 3 m siete immuni alla paura;Colpi radianti:Gli attacchi con armi infliggono 1d8 danni radianti extra;Tocco ristoratore:Con Imposizione delle mani rimuovi condizioni;Espansione dell'aura:Il raggio delle tue aure sale a 9 m;Errante:+3 m di velocità e velocità di scalata e nuoto;Instancabile:Recuperi PF temporanei e riduci l'esaurimento;Cacciatore implacabile:Il danno subito non interrompe la concentrazione su Marchio del Cacciatore;Velo della natura:Ti nascondi come azione bonus (usi limitati);Cacciatore preciso:Hai vantaggio ai tuoi attacchi contro il bersaglio di Marchio del Cacciatore;Sensi ferini:Percezione cieca entro 9 m;Uccisore di nemici:Il danno di Marchio del Cacciatore sale a d10;Colpo astuto:Rinunci a dadi di Attacco furtivo per un effetto - Veleno (1d6, TS COS o avvelenato), Sgambetto (1d6, TS DES o prono) o Ritirata (1d6, ti muovi di metà velocità senza provocare);Talento affidabile:Le prove con competenza hanno come minimo 10 sul d20;Colpo astuto migliorato:Puoi usare due effetti di Colpo astuto;Colpi malvagi:Nuovi effetti di Colpo astuto - Stordire (2d6, TS COS), Accecare (3d6, TS DES) e Mettere KO (6d6, TS COS o incosciente);Mente sfuggente:Competenza nei TS di SAG e CAR;Sfuggente:Nessun attacco ha vantaggio contro di te se non sei incapacitato;Colpo di fortuna:Trasformi un tiro mancato in un 20 (una volta per riposo);Incarnazione stregonesca:Attivi Magia innata spendendo punti stregoneria e usi due Metamagie sullo stesso incantesimo;Metamagia ulteriore:Impari due Metamagie in più;Apoteosi arcana:Con Magia innata attiva usi una Metamagia ogni turno senza costo;Contattare il patrono:Lanci Contattare altro piano senza slot e senza rischi;Arcanum mistico (6°):Un incantesimo di 6° livello da lanciare una volta per riposo lungo;Arcanum mistico (7°):Un incantesimo di 7° livello da lanciare una volta per riposo lungo;Arcanum mistico (8°):Un incantesimo di 8° livello da lanciare una volta per riposo lungo;Arcanum mistico (9°):Un incantesimo di 9° livello da lanciare una volta per riposo lungo;Maestro occulto:Recuperi tutti gli slot del Patto con 1 minuto di concentrazione;Maestria negli incantesimi:Un incantesimo di 1° e uno di 2° livello si lanciano a volontà al loro livello;Incantesimi firma:Due incantesimi di 3° livello sempre preparati, lanciabili una volta gratis per riposo`));
for(let n=3;n<=10;n++)FD['Attacco furtivo '+n+'d6']=n+'d6 danni extra con vantaggio o alleato adiacente';
const FA=Object.fromEntries(Object.entries(DM(`Atletico:0,1;Resiliente:0,1,2,3,4,5;Osservatore:3,4;Armatura Pesante:0,2;Attore:5;Carica:0,1;Cuoco:2,4;Schiacciatore:0,2;Durevole:2;Toccato dalle Fate:3,4,5;Lottatore:0,1;Ispirare Leader:4,5;Mente Acuta:3;Armatura Leggera:0,1;Addestramento con Armi Marziali:0,1;Maestro Armature Medie:0,1;Toccato dall'Ombra:3,4,5;Esperto di Abilità:0,1,2,3,4,5;Maestro d'Armi:0,1;Telecinetico:3,4,5;Telepatico:3,4,5;Tiratore Scelto:1;Armi Possenti:0;Maestro di Scudi:0;Sentinella:0,1;Incantatore da Guerra:3,4,5;Esperto di Balestre:1;Duellante Difensivo:1;Combattente Montato:0,1,2;Perforatore:0,1;Avvelenatore:1,3;Maestro di Armi Lunghe:0,1;Tagliatore:0,1;Veloce:1,2;Tiratore di Incantesimi:3,4,5;Adepto Elementale:3,4,5;Incantatore Rituale:3,4,5;Combattente con Due Armi:0,1`)).map(([k,v])=>[k,v.split(',').map(Number)]));
function fsel(v){$('fd').textContent=FT[v]||'';let a=FA[v],e=$('fab');if(a){e.style.display='';e.innerHTML=a.map(i=>`<option value="${i}">+1 ${AB[i]}</option>`).join('')}else{e.style.display='none';e.innerHTML=''}}
let XC=null;const SDF={};const SDX={'Berserker':`3~Frenesia~Se usi Attacco sconsiderato durante l'Ira, il primo bersaglio colpito in un turno con un attacco basato su FOR subisce danni extra pari a tanti d6 quanto il bonus ai danni dell'Ira|6~Ira insensata~Durante l'Ira sei immune ad affascinato e spaventato; se lo sei quando entri in Ira, la condizione termina|10~Ritorsione~Quando una creatura entro 1,5 m ti danneggia, usi una reazione per attaccarla in mischia con un'arma o a mani nude|14~Presenza intimidatoria~Azione bonus: le creature a tua scelta entro 9 m fanno un TS SAG (CD 8 + FOR + competenza) o sono spaventate per 1 minuto; si recupera con riposo lungo o spendendo un uso di Ira`,'Sapienza':`3~Competenze bonus~Competenza in tre abilità a scelta|3~Parole taglienti~Reazione: spendi Ispirazione bardica per sottrarre il dado a un attacco, danno o prova di una creatura entro 18 m|6~Scoperte magiche~Impari due incantesimi da qualsiasi lista (Chierico, Druido o Mago)|14~Abilità impareggiabile~Usi Ispirazione bardica su una tua prova fallita; se fallisce ancora non la consumi`,'Vita':`3~Discepolo della Vita~Gli incantesimi di cura su altri curano 2 PF più il livello dell'incantesimo in più|3~Preservare la Vita~Incanalare Divinità: ripristini PF pari a 5 volte il livello da Chierico, divisi tra creature entro 9 m (fino a metà dei loro PF massimi)|3~Incantesimi del Dominio~Sempre preparati: Aiuto, Benedizione, Cura Ferite, Ristorare Inferiore (3°); Parola Guaritrice di Massa, Rianimare (5°); Aura di Vita, Interdizione alla Morte (7°); Ristorare Superiore, Cura Ferite di Massa (9°)|6~Guaritore benedetto~Quando curi altri con un incantesimo, curi anche te di 2 PF più il livello dell'incantesimo|17~Guarigione suprema~Nelle cure i dadi danno sempre il valore massimo`,'Terra':`3~Aiuto della Terra~Azione Magia spendendo un uso di Forma selvatica: scegli un punto entro 18 m, sfera di 3 m, le creature scelte fanno un TS COS o subiscono 2d6 danni necrotici (metà se riescono) e una creatura a tua scelta recupera 2d6 PF (3d6 al 10°, 4d6 al 14°)|3~Incantesimi del Circolo~A ogni riposo lungo scegli un terreno (Aride, Polare, Temperato o Tropicale) e hai sempre preparati i suoi incantesimi|6~Recupero naturale~Lanci gratis un incantesimo del Circolo di livello 1+ una volta per riposo lungo e con un riposo breve recuperi slot (livello combinato fino a metà livello da Druido, nessuno di 6° o più)|10~Difesa della natura~Sei immune ad avvelenato e hai resistenza a un danno legato al terreno (Aride fuoco, Polare freddo, Temperato fulmine, Tropicale veleno)|14~Santuario della natura~Azione Magia spendendo Forma selvatica: alberi e rampicanti spettrali in un cubo di 4,5 m entro 36 m per 1 minuto, mezza copertura per te e gli alleati, che ottengono anche la resistenza della Difesa della natura`,'Campione':`3~Critico migliorato~Gli attacchi con armi e a mani nude sono critici con 19-20|3~Atleta straordinario~Vantaggio a iniziativa e Atletica; dopo un critico ti muovi di metà velocità senza provocare|7~Stile di combattimento aggiuntivo~Un secondo talento di stile di combattimento|10~Guerriero eroico~A inizio turno in combattimento ottieni Ispirazione eroica se non ce l'hai|15~Critico superiore~I critici avvengono con 18-20|18~Sopravvissuto~Vantaggio ai TS contro morte; a inizio turno con meno della metà dei PF recuperi 5 + COS PF`,'Mano Aperta':`3~Tecnica della Mano Aperta~Quando colpisci con un attacco della Raffica di colpi imponi un effetto: Disorientare (niente attacchi di opportunità fino al suo prossimo turno), Spinta (TS FOR o spinto di 4,5 m) o Atterrare (TS DES o prono)|6~Integrità del corpo~Azione bonus: ti curi del dado Arti marziali + SAG (usi pari al mod SAG per riposo lungo)|11~Passo rapido~Quando usi un'azione bonus diversa da Passo del vento puoi usare subito anche Passo del vento|17~Palmo tremante~Dopo un colpo senza armi spendi 4 Ferocia per innescare vibrazioni che durano giorni pari al livello. Poi puoi attivarle: TS COS o 10d12 danni da forza (metà se riesce)`,'Devozione':`3~Arma sacra~Incanalare Divinità: per 10 minuti un'arma ottiene bonus al colpire pari al mod CAR, emette luce e infligge danni radianti|3~Incantesimi del Giuramento~Sempre preparati: Protezione dal Bene e dal Male, Scudo della Fede (3°); Aiuto, Zona di Verità (5°); Faro di Speranza, Dissolvi Magia (9°); Libertà di Movimento, Guardiano della Fede (13°); Comunione, Colonna di Fuoco (17°)|7~Aura di devozione~Tu e gli alleati nell'aura siete immuni ad affascinato|15~Punizione protettiva~Quando usi Punizione Divina, tu e gli alleati nell'aura avete mezza copertura fino al tuo prossimo turno|20~Nimbo sacro~Azione bonus: per 10 minuti l'aura emana luce solare, hai vantaggio ai TS contro Immondi e Non morti e i nemici che iniziano il turno nell'aura subiscono danni radianti pari a CAR + competenza (una volta per riposo lungo, o spendendo uno slot di 5° livello)`,'Cacciatore':`3~Conoscenza del cacciatore~Marchio del Cacciatore ti rivela immunità, resistenze e vulnerabilità del bersaglio|3~Preda del cacciatore~Scegli Uccisore di colossi (danni extra a un bersaglio ferito) o Spezzatore di orde (attacco extra a un'altra creatura vicina)|7~Tattiche difensive~Scegli Fuga dall'orda (svantaggio agli attacchi di opportunità contro di te) o Difesa multiattacco|11~Preda superiore~Marchio del Cacciatore danneggia anche un secondo bersaglio entro 9 m|15~Difesa superiore~Reazione: resistenza a un danno appena subito`,'Furfante':`3~Mani veloci~Azione bonus: prova di Rapidità di mano (scassinare, disarmare trappole, borseggiare) oppure usare un oggetto o un oggetto magico|3~Lavoro al piano di sopra~Hai velocità di scalata pari alla velocità e salti usando la DES|9~Furtività suprema~Opzione di Colpo astuto (1d6): l'attacco non ti rivela se finisci il turno dietro copertura di tre quarti o totale|13~Usare dispositivi magici~Ti sintonizzi con 4 oggetti magici, 1d6 (con 6 non spendi cariche) e usi qualsiasi pergamena con INT (prova di Arcano CD 10 + livello per quelle sopra il 1°)|17~Riflessi del ladro~Nel primo round di ogni combattimento hai due turni (iniziativa normale e iniziativa -10)`,'Draconico':`3~Resilienza draconica~PF massimi +3 e +1 per ogni livello da Stregone; senza armatura la CA è 10 + DES + CAR|3~Incantesimi draconici~Sempre preparati: Alterare Se Stessi, Sfera Cromatica, Comando (3°); Paura, Volare (5°); Occhio Arcano, Charme su Mostri (7°); Conoscenza Leggendaria (9°)|6~Affinità elementale~Resistenza al danno del tuo drago e aggiungi CAR ai danni degli incantesimi di quel tipo|14~Ali di drago~Azione bonus: ali con volo pari alla velocità (una volta per riposo lungo)|18~Compagno draconico~Lanci Evocare Drago senza slot una volta per riposo lungo`,'Immondo':`3~Benedizione dell'Oscuro~Se riduci un nemico a 0 PF ottieni PF temporanei pari a CAR + livello da Warlock|3~Incantesimi dell'Immondo~Sempre preparati: Mani Brucianti, Comando, Raggio Rovente, Suggestione (3°); Palla di Fuoco, Nube Puzzolente (5°); Scudo di Fuoco, Muro di Fuoco (7°); Vincolo, Piaga di Insetti (9°)|6~Fortuna dell'Oscuro~Aggiungi 1d10 a una prova o a un TS (usi pari a CAR)|10~Resilienza immonda~Resistenza a un tipo di danno scelto dopo ogni riposo|14~Scagliare nell'Inferno~Una volta per turno, se colpisci, il bersaglio fa un TS CAR o sparisce nell'inferno: subisce 8d10 danni psichici (se non è un Immondo) ed è incapacitato fino alla fine del tuo prossimo turno. Una volta per riposo lungo, o spendendo uno slot del Patto`,'Evocazione':`3~Esperto di evocazione~Copiare incantesimi di evocazione nel libro costa metà tempo e oro|3~Trucchetto potente~Se un bersaglio supera il TS o evita il tuo trucchetto da danno, subisce comunque metà danni|6~Modellare incantesimi~Negli incantesimi di evocazione ad area proteggi alleati fino a 1 + livello dell'incantesimo|10~Evocazione potenziata~Aggiungi INT ai danni di un incantesimo di evocazione|14~Sovraccaricare~Con uno slot di livello 1-5 infliggi il danno massimo con un incantesimo; la prima volta senza conseguenze, poi subisci 2d12 danni necrotici per livello dello slot (+1d12 a ogni uso successivo)`};Object.assign(SDX,{'Cuore Selvaggio':`3~Parlare con gli animali~Lanci come rituali Parlare con gli Animali e Senso Bestiale (SAG)|3~Ira dei selvaggi~A ogni Ira scegli Orso (resistenza ai danni tranne forza, necrotico, psichico e radiante), Aquila (Scatto e Disimpegno come azione bonus) o Lupo (alleati con vantaggio contro nemici adiacenti a te)|6~Aspetto dei selvaggi~Scegli Gufo (scurovisione), Pantera (scalata) o Salmone (nuoto)|10~Parlare con la natura~Lanci Comunione con la Natura come rituale|14~Potere dei selvaggi~A ogni Ira scegli Falco (volo), Leone (nemici vicini svantaggiati contro altri) o Ariete (atterri creature Grandi o più piccole)`,'Albero del Mondo':`3~Vitalità dell'Albero~Entrando in Ira ottieni PF temporanei; a inizio turno in Ira dai PF temporanei a un alleato vicino|6~Rami dell'Albero~Reazione: trascini una creatura entro 9 m vicino a te (TS FOR)|10~Radici battenti~Aumenti la portata delle armi da mischia e ottieni le maestrie Spingere e Atterrare|14~Viaggio lungo l'Albero~Durante l'Ira teletrasporti te e gli alleati vicini (da verificare)`,'Fanatico':`3~Furia divina~Durante l'Ira il primo bersaglio colpito in un turno subisce danni necrotici o radianti extra|3~Guerriero degli dèi~Riserva di dadi con cui ti curi come azione bonus|6~Concentrazione fanatica~Una volta per Ira ripeti un TS fallito con bonus pari ai danni dell'Ira|10~Presenza zelante~Azione bonus: alleati vicini con vantaggio ad attacchi e TS fino al tuo prossimo turno|14~Ira degli dèi~Per 1 minuto assumi una forma divina con volo e resistenze (da verificare)`,'Danza':`3~Passo abbagliante~Senza armatura CA 10 + DES + CAR; colpi senza armi con d6 + DES e danni extra con Ispirazione bardica|6~Movimento ispirante~Reazione: ti muovi con un alleato; a iniziativa dai il dado di Ispirazione anche agli alleati|14~Evasione guida~Elusione per te e gli alleati vicini`,'Valore':`3~Ispirazione in combattimento~Il dado di Ispirazione bardica si aggiunge ai danni o alla CA|3~Addestramento marziale~Competenza con armature medie, scudi e armi marziali|6~Attacco extra~Attacchi due volte con l'azione Attacco|14~Magia di battaglia~Dopo aver lanciato un incantesimo con l'azione puoi attaccare come azione bonus`,'Glamour':`3~Magia ammaliante~Lanci gratis Charme su Persone e Immagine Speculare una volta per riposo lungo|3~Mantello di ispirazione~Azione bonus: spendi Ispirazione per dare PF temporanei e movimento agli alleati|6~Mantello di maestà~Azione bonus: Comando senza slot per 1 minuto|14~Maestà incrollabile~Gli attaccanti devono superare un TS CAR o non possono colpirti (da verificare)`,'Luce':`3~Bagliore di protezione~Reazione: svantaggio a un attacco contro te o un alleato entro 9 m|3~Radiosità dell'alba~Incanalare Divinità: danni radianti ai nemici vicini (TS COS dimezza) e dissolvi oscurità magica|3~Incantesimi del Dominio~Mani Brucianti, Fuoco Fatato, Raggio Rovente, Vedere Invisibile (3°); Palla di Fuoco, Luce del Giorno (5°); Occhio Arcano, Muro di Fuoco (7°); Scrutare, Colonna di Fuoco (9°)|6~Bagliore potenziato~Il Bagliore di protezione si recupera con riposo breve e dà PF temporanei (da verificare)|17~Corona di luce~Aura di luce solare: i nemici hanno svantaggio ai TS contro i tuoi incantesimi di fuoco e radianti`,'Inganno':`3~Benedizione dell'Ingannatore~Una creatura toccata ha vantaggio alle prove di Furtività|3~Invocare Duplicità~Incanalare Divinità: crei un duplicato illusorio da cui lanci incantesimi e che ti dà vantaggio agli attacchi|6~Trasposizione~Quando usi Invocare Duplicità puoi scambiare il tuo posto con il duplicato|17~Duplicità migliorata~Crei più duplicati (da verificare)`,'Guerra':`3~Attacco guidato~Incanalare Divinità: +10 a un tiro per colpire dopo averlo visto|3~Sacerdote di guerra~Azione bonus: un attacco con arma (usi pari al mod SAG)|6~Benedizione del dio della guerra~Con Incanalare Divinità lanci Scudo della Fede o Arma Spirituale senza slot|17~Avatar della battaglia~Resistenza ai danni contundenti, perforanti e taglienti`,'Luna':`3~Forme del Circolo~In Forma selvatica ottieni PF temporanei pari a 3 volte il livello e CA 13 + SAG, con forme più potenti|3~Incantesimi lunari~Cura Ferite, Raggio Lunare, Luce Stellare sempre preparati|6~Forme migliorate~Gli attacchi in Forma selvatica infliggono danni radianti extra (da verificare)|10~Passo lunare~Azione bonus: teletrasporto di 9 m e vantaggio al prossimo attacco|14~Forma lunare~Potenzia danni radianti e Passo lunare (da verificare)`,'Mare':`3~Furia del mare~Azione bonus spendendo Forma selvatica: aura di tempesta che danneggia i nemici vicini (da verificare)|6~Affinità acquatica~Aura più grande e velocità di nuoto|10~Nato dalla tempesta~Volo e resistenza durante l'aura|14~Dono oceanico~Estendi l'aura a un alleato`,'Stelle':`3~Mappa stellare~Hai la mappa stellare con Raggio Guida e Guida preparati|3~Forma stellare~Spendi Forma selvatica per una costellazione a scelta (Arciere, Calice o Drago)|6~Presagio cosmico~Reazione (usi pari a SAG): aggiungi o togli 1d6 al tiro di una creatura vicina|10~Costellazioni cangianti~Cambi costellazione in forma stellare|14~Pieno di stelle~In forma stellare hai resistenza a contundente, perforante e tagliente`,'Maestro di Battaglia':`3~Superiorità in combattimento~Quattro dadi di superiorità (d8) e due manovre; i dadi si recuperano con riposo breve|3~Studente della guerra~Competenza con uno strumento da artigiano|7~Conosci il tuo nemico~Azione bonus: ottieni informazioni su una creatura (dado di superiorità o una volta per riposo)|10~Superiorità migliorata~I dadi diventano d10|15~Spietato~Recuperi un dado di superiorità quando tiri iniziativa`,'Cavaliere Mistico':`3~Incantesimi da mago~Lanci incantesimi del Mago usando INT (trucchetti e incantesimi)|3~Legame con l'arma~Leghi un'arma e la richiami nella mano|7~Guerra magica~Dopo un trucchetto attacchi con un'azione bonus|10~Colpo mistico~Il bersaglio colpito ha svantaggio al TS contro il tuo prossimo incantesimo|15~Carica arcana~Con Impeto di azione ti teletrasporti di 9 m`,'Combattente Psichico':`3~Potere psionico~Dadi psionici (d6) per Colpo psionico, Barriera protettiva e Impulso telecinetico|7~Adepto telecinetico~Salto telecinetico e spinta con i dadi psionici|10~Mente protetta~Resistenza ai danni psichici|15~Baluardo di forza~Protezione per te e gli alleati|18~Maestro telecinetico~Lanci Telecinesi con i dadi psionici (da verificare)`,'Misericordia':`3~Mani di guarigione e di danno~Con Raffica di colpi curi (dado Arti marziali + SAG) o infliggi danni necrotici extra|3~Strumenti della Misericordia~Competenza in Medicina e Intuizione? e kit di erboristeria (da verificare)|6~Tocco del medico~Le tue cure rimuovono condizioni; i colpi avvelenano|11~Raffica di guarigione e danno~Usi Mani di guarigione e di danno senza costo|17~Mano della Misericordia finale~Riporti in vita una creatura morta da poco (5 Ferocia)`,'Elementi':`3~Sintonia elementale~Azione bonus: i colpi hanno portata maggiore e danni elementali|3~Manipolare gli elementi~Impari Elementalismo|6~Esplosione elementale~Danni elementali ad area con Ferocia (da verificare)|11~Passo degli elementi~Volo e nuoto con la velocità|17~Epitome elementale~Resistenza e danni extra elementali`,'Ombra':`3~Arti dell'ombra~Spendi Ferocia per lanciare Oscurità, Scurovisione, Passo senza Tracce o Silenzio|6~Passo d'ombra~Azione bonus: teletrasporto di 18 m tra zone di penombra|11~Manto d'ombra~Diventi invisibile in penombra|17~Opportunista~Reazione: attacchi chi è colpito da un alleato`,'Gloria':`3~Atleta impareggiabile~Azione bonus: bonus a Atletica e Acrobazia e salto maggiore (Incanalare Divinità)|3~Punizione ispiratrice~Dopo Punizione Divina distribuisci PF temporanei|3~Incantesimi del Giuramento~Fulmine Guida, Eroismo (3°); Potenziare Abilità, Arma Magica (5°); Velocità, Protezione dall'Energia (9°); Compulsione, Libertà di Movimento (13°); Comunione, Colonna di Fuoco (17°)|7~Aura di vivacità~+3 m di velocità a te e agli alleati nell'aura|15~Difesa gloriosa~Reazione: riduci il danno a un alleato e contrattacchi`,'Vendetta':`3~Voto di inimicizia~Incanalare Divinità: vantaggio agli attacchi contro un nemico per 1 minuto|3~Incantesimi del Giuramento~Anatema, Marchio del Cacciatore (3°); Blocca Persone, Passo Velato (5°); Velocità, Protezione dall'Energia (9°); Esilio, Porta Dimensionale (13°); Blocca Mostri, Scrutare (17°)|7~Vendicatore implacabile~Dopo un attacco di opportunità ti muovi verso il bersaglio|15~Anima di vendetta~Reazione: attacchi chi attacca dopo il tuo Voto|20~Angelo vendicatore~Ali e aura di terrore (da verificare)`,'Antichi':`3~Ira della natura~Incanalare Divinità: rampicanti spettrali trattengono un nemico|3~Incantesimi del Giuramento~Colpo Intrappolante, Parlare con gli Animali (3°); Raggio Lunare, Passo Velato (5°); Crescita Vegetale, Protezione dall'Energia (9°); Tempesta di Ghiaccio, Pelle di Pietra (13°)|7~Aura di protezione magica~Resistenza ai danni degli incantesimi per te e gli alleati vicini|15~Sentinella indistruttibile~Quando scendi a 0 PF resti a 1 PF (una volta per riposo lungo)`,'Signore delle Bestie':`3~Compagno primordiale~Evochi una bestia compagna (Terra, Cielo o Mare) che combatte con te|7~Addestramento eccezionale~Azione bonus: comandi la bestia a Scatto, Disimpegno o Aiuto|11~Furia bestiale~Il compagno infligge danni extra|15~Condividere incantesimi~Gli incantesimi su di te colpiscono anche il compagno`,'Vagabondo Fatato':`3~Colpi terribili~Danni psichici extra una volta per turno con un'arma|3~Fascino ultraterreno~Aggiungi SAG alle prove di CAR e ottieni competenza|7~Svolta ammaliante~Reazione: ripeti un TS contro charme o paura|11~Rinforzi fatati~Evochi una creatura fatata gratis una volta per riposo lungo|15~Vagabondo nebbioso~Lanci Passo Velato gratis un numero di volte pari a SAG`,'Cacciatore delle Ombre':`3~Vista dell'ombra~Scurovisione maggiore e invisibile a chi usa solo scurovisione|3~Imboscata temibile~Aggiungi SAG all'iniziativa e al primo turno hai un attacco extra con danni extra|7~Mente di ferro~Competenza nei TS di SAG|11~Raffica dell'inseguitore~Se manchi un attacco ne fai un altro|15~Schivata nell'ombra~Reazione: imponi svantaggio a un attacco contro di te`,'Assassino':`3~Assassinare~Vantaggio all'iniziativa; nel primo round hai vantaggio contro chi non ha agito e danni extra|3~Strumenti dell'assassino~Competenza con il kit di travestimento e il kit del veleno|9~Strumenti letali~Potenzi i veleni sulle armi|13~Veleni migliorati~I tuoi veleni ignorano la resistenza|17~Colpo mortale~Danni raddoppiati contro chi è sorpreso (TS COS)`,'Mistificatore Arcano':`3~Incantesimi da mago~Lanci incantesimi del Mago usando INT|3~Mano magica prestigiatrice~Mano Magica invisibile che può rubare e usare oggetti|9~Imboscata magica~Se sei nascosto i bersagli hanno svantaggio ai TS contro i tuoi incantesimi|13~Truffatore versatile~Sposti gli effetti di Mano Magica sul bersaglio|17~Ladro di incantesimi~Rubi un incantesimo lanciato contro di te`,'Soulknife':`3~Lame psichiche~Crei lame psichiche (d6) da usare come armi con attacco bonus d4|3~Energia psionica~Dadi psionici (d6) per Sussurri psichici e Cura del Sé|9~Lame vaganti~Colpi guidati e teletrasporto psichico|13~Velo psichico~Diventi invisibile per breve tempo|17~Rendere la mente~Stordisci con le lame (TS SAG)`,'Selvaggia':`3~Sovratensione di magia selvaggia~Dopo aver lanciato un incantesimo puoi tirare sulla tabella della magia selvaggia|3~Maree del caos~Vantaggio a un tiro del d20 e poi la magia selvaggia scatta|6~Piegare la fortuna~Reazione (2 punti stregoneria): ±1d4 al tiro di un'altra creatura|14~Magia controllata~Scegli il risultato della sovratensione|18~Bombardamento di incantesimi~Danni extra con gli incantesimi`,'Meccanica':`3~Ripristinare l'equilibrio~Reazione: annulli vantaggio o svantaggio su un tiro vicino|3~Incantesimi meccanici~Allarme, Protezione dal Bene e dal Male (3°); Aiuto, Ristorare Inferiore (5°); Dissolvi Magia, Protezione dall'Energia (7°); Libertà di Movimento (9°); Ristorare Superiore, Muro di Forza (11°)|6~Bastione della legge~Spendi punti stregoneria per uno scudo di dadi assorbi danni|14~Trance dell'ordine~Minimo 10 sui tiri del d20 per breve tempo|18~Cavalcata meccanica~Evochi spiriti che curano e riparano`,'Aberrante':`3~Parola telepatica~Telepatia con una creatura entro 9 m|3~Incantesimi psionici~Braccia di Hadar, Calmare Emozioni, Individuazione dei Pensieri, Sussurri Dissonanti, Aculeo Mentale (3°)|6~Stregoneria psionica~Lanci incantesimi psionici con punti stregoneria senza componenti|6~Difese psichiche~Resistenza ai danni psichici e vantaggio contro charme e paura|14~Rivelazione in carne~Trasformazione aberrante con vari poteri|18~Implosione di distorsione~Teletrasporto con danni a chi è vicino (da verificare)`,'Arcifata':`3~Passi fatati~Lanci Passo Velato un numero di volte pari a CAR e scegli un effetto aggiuntivo|3~Incantesimi dell'Arcifata~Calmare Emozioni, Fuoco Fatato, Passo Velato, Forza Fantasma (3°); Intermittenza, Crescita Vegetale (5°); Dominare Bestie, Invisibilità Superiore (7°); Dominare Persone, Apparenza (9°)|6~Fuga nebbiosa~Reazione: Passo Velato quando subisci danni|10~Difese seducenti~Immune a charme e puoi riflettere l'effetto|14~Magia stregata~Dopo un incantesimo ammaliare o illusione, Passo Velato gratis`,'Celestiale':`3~Luce risanatrice~Riserva di d6 per curare come azione bonus|3~Incantesimi del Celestiale~Aiuto, Cura Ferite, Fulmine Guida, Ristorare Inferiore (3°); Rianimare, Luce del Giorno (5°); Guardiano della Fede, Muro di Fuoco (7°); Ristorare Superiore (9°); trucchetti Luce e Fiamma Sacra|6~Anima radiosa~Resistenza radiante e CAR ai danni di fuoco e radianti|10~Resilienza celestiale~PF temporanei dopo ogni riposo|14~Vendetta ardente~Quando cadi a 0 PF esplodi in luce e ti curi (da verificare)`,'Grande Antico':`3~Mente risvegliata~Telepatia con creature entro 9 m|3~Magia psichica~Gli incantesimi infliggono danni psichici e puoi lanciarli senza componenti|6~Combattente chiaroveggente~Affascini una creatura e hai vantaggio contro di lei|10~Scudo del pensiero~Resistenza ai danni psichici e riflessione|14~Creare servitore~Trasformi una creatura in un servitore (da verificare)`,'Abiurazione':`3~Esperto di abiurazione~Copiare incantesimi di abiurazione costa metà tempo e oro|3~Protezione arcana~Lanciando abiurazioni crei una barriera con PF pari a 2 volte il livello + INT|6~Barriera proiettata~Reazione: proteggi un alleato con la barriera|10~Spezzaincantesimi~Dissolvi Magia più facile e senza slot (da verificare)|14~Resistenza agli incantesimi~Vantaggio ai TS contro incantesimi e resistenza ai loro danni`,'Divinazione':`3~Esperto di divinazione~Copiare incantesimi di divinazione costa metà tempo e oro|3~Prodigio~Tiri due d20 a riposo lungo e sostituisci i tiri di qualsiasi creatura|6~Divinazione esperta~Recuperi slot lanciando divinazioni|10~Terzo occhio~Potenziamenti sensoriali a scelta (da verificare)|14~Prodigio superiore~Tiri tre dadi di Prodigio`,'Illusione':`3~Esperto di illusione~Copiare incantesimi di illusione costa metà tempo e oro|3~Illusioni migliorate~Illusione Minore può creare suono e immagine insieme|6~Creature fantasma~Le tue evocazioni illusorie sono bestie o fate fantasma|10~Sé illusorio~Reazione: l'attacco contro di te manca|14~Realtà illusoria~Rendi reale un oggetto illusorio per un attimo`});Object.entries(SDX).forEach(([k,v])=>SDF[k]=v.split('|').map(x=>x.split('~')));
const EFH='Effetti: FOR DES COS INT SAG CAR +n, CA, CAA (CA con armatura), PF, PF/LIV, VEL (m), INIZ (anche +PB o +SAG), ATT, ATTD (a distanza), DAN, TS+SAG (competenza nel TS, anche TS+TUTTI), TSCAR (bonus CAR ai TS), MEZZA (mezza competenza), DEXC+1 (limite DES armature medie), MARZ (armi marziali), RIT20 (ritira gli 1 sul d20), RIT2 (ritira 1 e 2 sui danni), MIGL (danni: tiri due volte), RES_fuoco, IMM_veleno. Esempio: FOR+2 CA+1 VEL+3';
const FE={'Addestramento con Armi Marziali':'MARZ','Addestramento marziale':'MARZ','Veloce':'VEL+3','Mobile':'VEL+3','Allerta':'INIZ+PB','Difesa':'CAA+1','Tiro con Arco':'ATTD+2','Duellare':'DAN+2','Armi a Due Mani':'MIN3','Attaccante Selvaggio':'MIGL','Movimento veloce':'VEL+3','Movimento senza armatura':'VEL+MON','Errante':'VEL+3','Campione primordiale':'FOR+4 COS+4','Corpo e mente':'DES+4 SAG+4','Resilienza draconica':'PF+3 PF/LIV+1','Competenza tuttofare':'MEZZA','Sopravvissuto disciplinato':'TS+TUTTI','Aura di protezione':'TSCAR','Mente di ferro':'TS+SAG','Mente sfuggente':'TS+SAG TS+CAR','Imboscata temibile':'INIZ+SAG','Aura di vivacità':'VEL+3','Maestro Armature Medie':'DEXC+1','Armatura Leggera':'ARML ARMS','Armatura Media':'ARMM ARMS','Armatura Pesante':'ARMH'},FE2={'Fortunato':'RIT20','Robustezza nanica':'PF/LIV+1','Resilienza nanica':'RES_veleno','Resistenza celestiale':'RES_necrotico RES_radiante'};
function pe(t){let o={ab:[0,0,0,0,0,0],ca:0,caa:0,hpl:0,hp:0,vel:0,ini:0,att:0,attd:0,dan:0,dexc:0,marz:0,r20:0,r2:0,min3:0,migl:0,mezza:0,tsc:0,al:0,am:0,ah:0,as:0,ts:[],inix:[],res:[],vis:0},l=C()?C().lv:1;(t||'').split(/[\s,]+/).forEach(x=>{x=x.trim();if(!x)return;let X=x.toUpperCase(),m=/^(FOR|DES|COS|INT|SAG|CAR)([+-]\d+)$/.exec(X);if(m){o.ab[AB.indexOf(m[1])]+=+m[2];return}m=/^TS\+(FOR|DES|COS|INT|SAG|CAR|TUTTI)$/.exec(X);if(m){if(m[1]=='TUTTI')o.ts.push(0,1,2,3,4,5);else o.ts.push(AB.indexOf(m[1]));return}m=/^INIZ\+(FOR|DES|COS|INT|SAG|CAR)$/.exec(X);if(m){o.inix.push(AB.indexOf(m[1]));return}if(X=='VEL+MON'){o.vel+=l>=18?9:l>=14?7.5:l>=10?6:l>=6?4.5:l>=2?3:0;return}m=/^(CAA|CA|PF\/LIV|PF|VEL|INIZ|ATTD|ATT|DAN|DEXC)([+-](?:\d+(?:\.\d+)?|PB))$/.exec(X);if(m){let k={CA:'ca',CAA:'caa','PF/LIV':'hpl',PF:'hp',VEL:'vel',INIZ:'ini',ATT:'att',ATTD:'attd',DAN:'dan',DEXC:'dexc'}[m[1]];o[k]+=m[2].slice(1)=='PB'?PB():+m[2];return}if(X=='MARZ')o.marz=1;if(X=='RIT20')o.r20=1;if(X=='RIT2')o.r2=1;if(X=='MIN3')o.min3=1;if(X=='ARML')o.al=1;if(X=='ARMM')o.am=1;if(X=='ARMH')o.ah=1;if(X=='ARMS')o.as=1;if(X=='MIGL')o.migl=1;if(X=='MEZZA')o.mezza=1;if(X=='TSCAR')o.tsc=1;m=/^(RES|IMM)_(.+)$/i.exec(x);if(m)o.res.push((m[1].toUpperCase()=='RES'?'resistenza ':'immunità ')+m[2].replace(/_/g,' '))});return o}
function EF(c){c=c||C();let o=pe('');if(!c)return o;let add=e=>{if(!e)return;e=pe(e);o.ab=o.ab.map((v,i)=>v+e.ab[i]);['ca','caa','hpl','hp','vel','ini','att','attd','dan','dexc'].forEach(k=>o[k]+=e[k]);['marz','r20','r2','min3','migl','mezza','tsc','al','am','ah','as'].forEach(k=>o[k]=o[k]||e[k]);o.ts=o.ts.concat(e.ts);o.inix=o.inix.concat(e.inix);o.res=o.res.concat(e.res)};
if(SPL[c.s]&&c.ln!=null){let q=SPL[c.s].o[c.ln];if(q){add(q.ef);if(q.vis)o.vis=Math.max(o.vis,q.vis)}}if(c.xo){if(c.xo['Ordine divino']==0)add('MARZ ARMH');if(c.xo['Ordine primordiale']==0)add('MARZ ARMM')}c.ft.forEach(f=>add(FE[f]));(c.xt||SP[c.s][3].split('; ')).forEach(x=>{let mm=/Scurovisione (\d+) m/.exec(x);if(mm)o.vis=Math.max(o.vis,+mm[1]);add(FE2[x.replace(/ \(.*|\s\d+ m$/,'')])});
CL[c.c][8].split('|').forEach(g=>{let l=+g.split(' ')[0];if(l>c.lv)return;g.slice(g.indexOf(' ')+1).split('; ').forEach(f=>{if(l==1&&c.xc&&!c.xc.includes(f))return;add(FE[f])})});
(SDF[c.sub]||[]).forEach(x=>{if(+x[0]<=c.lv)add(FE[x[1]])});
if(c.c>=12&&c.lv>=(CL[c.c][15]||1))add(CL[c.c][13]);if(c.s>=10)add(SP[c.s][7]);if(c.b>=16)add(BG[c.b][3]);add(c.ex);return o}
