<div class="c"><b>1. Giocatori</b>${d.pt.map((p,i)=>`<div class="c"><div class="r"><input value="${p.n}" onchange="DD().pt[${i}].n=this.value" style="flex:2"><button class="chip" onclick="DD().pt.splice(${i},1);sv();R()">Togli</button></div><div class="g"><label>PF<input type="number" value="${p.mh}" onchange="let q=DD().pt[${i}];q.mh=q.hp=+this.value"></label><label>CA<input type="number" value="${p.ac}" onchange="DD().pt[${i}].ac=+this.value"></label><label>Iniziativa<input type="number" value="${p.ini??''}" onchange="DD().pt[${i}].ini=+this.value"></label></div>${p.ci==null?`<div class="g"><label>Bonus ai TS<input type="number" value="${p.sv||0}" onchange="DD().pt[${i}].sv=+this.value"></label><label>Velocità (m)<input type="number" step="0.5" value="${p.vel||9}" onchange="DD().pt[${i}].vel=+this.value"></label></div>`:''}<div class="r"><small class="mu">Difese: ${dDfTxt(p)}</small><button class="chip" onclick="dDfM('p',${i})">+ Difesa o contrattacco</button>${(p.df||[]).length?`<button class="chip" onclick="DD().pt[${i}].df=[];sv();R()">Svuota</button>`:''}</div></div>`).join('')||'<p class="mu">Nessun giocatore.</p>'}<div class="r"><button class="b o" onclick="dPt()">+ Giocatore</button>${S.chs.length?'<button class="b o" onclick="dImp()">Importa dai miei personaggi</button>':''}</div></div>
