function dFxS(old){let n=$('fx1').value.trim();if(!n)return T('Dai un nome all\'effetto');let d=DD(),e={n,du:Math.max(1,+$('fx2').value||2),acb:+$('fx3').value||0,dot:$('fx4').value.trim(),dt:$('fx5').value.trim(),hot:$('fx6').value.trim(),sk:$('fx7').checked?1:0,ts:$('fx9').value,d:$('fx8').value.trim()};if(e.dot&&!isNaN(e.dot))e.dot=+e.dot;if(e.hot&&!isNaN(e.hot))e.hot=+e.hot;d.fxc=(d.fxc||[]).filter(x=>x.n!=n&&x.n!=old);d.fxc.push(e);if(old&&old!=n&&!(FXB[old]))d.fxd=d.fxd||[];fxSync();let u=dEn().ui;if(u)u.fx=n;closeM();sv();R()}
