function dFin(e){let d=DD();return e.win?`<div class="c"><h3>Vittoria!</h3><p>Totale PE: <b>${e.xp}</b>. A ogni giocatore vivo: <b>${e.sh} PE</b> (chi è morto non riceve nulla).</p><p>Monete (difficoltà <b>${e.dfn||'Media'}</b>): totale <b>${pf(e.co||0)}</b>, a ogni giocatore vivo <b>${pf(e.cs||0)}</b>.</p><p>Drop: <b>${e.dr?e.dr.n:'nessuno'}</b>${e.dr&&e.dr.d?'<br><small>'+e.dr.d+'</small>':''}${e.dr&&e.dr.st?'<br><small class="mu">'+e.dr.st.join('<br>')+'</small>':''}<br><button class="chip" style="margin-top:6px" onclick="dReDrp()">${e.dr?'Rigenera il drop':'Tira un drop comunque'}</button></p>${d.pt.map(p=>`<div class="row" style="cursor:default"><span>${p.n}</span><b>${p.dead?'morto':'+'+e.sh+' PE, '+pf(e.cs||0)}</b></div>`).join('')}${d.pt.some(p=>p.ci!=null&&!p.dead)?'<button class="b" onclick="dXp()">Assegna PE e monete ai personaggi collegati</button>':''}${e.dr&&e.dr.allow&&!d.pt.some(p=>p.ci!=null&&!p.dead&&dOk(e.dr,p))?'<p class="mu">Nessun giocatore può usare questo oggetto secondo le regole: rigenera il drop.</p>':''}${e.dr&&d.pt.some(p=>p.ci!=null&&!p.dead&&dOk(e.dr,p))?`<p style="margin-top:10px"><small class="mu">Solo chi può usarlo secondo le regole.</small><br><label>Dai il drop a<select id="dpr">${d.pt.filter(p=>p.ci!=null&&!p.dead&&dOk(e.dr,p)).map(p=>`<option value="${p.ci}" ${e.dr&&e.dr.ci==p.ci?'selected':''}>${p.n}</option>`).join('')}</select></label><button class="b o" onclick="dDrp()">Assegna il drop</button></p>`:''}</div><button class="b o" onclick="dRes()">Nuovo scontro</button>`:`<div class="c"><h3>Sconfitta</h3><p>Tutti i giocatori sono caduti.</p></div><button class="b o" onclick="dRes()">Nuovo scontro</button>`}
function dXp(){let d=DD(),e=dEn();if(e.xg)return T('PE e monete sono già stati assegnati.');e.xg=1;d.pt.forEach(p=>{if(p.ci!=null&&!p.dead&&S.chs[p.ci]){S.chs[p.ci].xp+=e.sh;dAddMR(S.chs[p.ci],e.cs||0);if(p.lvp)lvRew(p,{xp:e.sh,mr:e.cs||0})}});sv();T('PE e monete assegnati ai personaggi collegati')}
function dRes(){let d=DD();if(d.en&&d.en.ph=='f')lvFinalAll();d.en=null;d.pt.forEach(p=>{p.rx=0;p.dsv=0;p.fx=[];p.tp=0;p.ds=[0,0];p.dead=0;p.stab=0;p.ini=null;if(p.hp<=0)p.hp=1});dSyncHp(1);sv();R()}
