function rd1(){let w=W,g=i=>$(i)&&$(i).value;if(w.s==1){w.n=g('n');w.c=+g('c');w.s2=+g('sp');w.b=+g('b')}if(w.s==2){w.st=AB.map((_,i)=>+g('s'+i)||10);w.ba2=+g('ba2');w.ba1=+g('ba1');w.bat=!!($('bat')&&$('bat').checked)}if(w.s==3)['tr','id','lg','df','ap'].forEach(k=>w[k]=g(k));if(w.s==3)w.al=+g('al');if(w.s==4)w.sk=[...document.querySelectorAll('.sk:checked')].map(x=>+x.value)}
