function lvSnapClean(o){if(!o||typeof o!='object'||o.v!==1||!['r','s','f','x'].includes(o.ph))return null;let N=(v,a,b)=>Number.isFinite(v)?Math.max(a,Math.min(b,Math.floor(v))):null,pl=(Array.isArray(o.pl)?o.pl:[]).slice(0,40).filter(x=>x&&Number.isInteger(x.id)).map(x=>({id:x.id,n:lvTx(x.n,40)})),fin=(Array.isArray(o.fin)?o.fin:[]).filter(x=>typeof x=='string'&&/^[0-9a-f]{8}$/.test(x)).slice(0,40),r={v:1,ph:o.ph,ts:Number.isFinite(o.ts)?o.ts:0,pl,fin};if(o.ph!='r')return r;r.rnd=N(o.rnd,1,1e6)||1;r.md=['bar','num','txt'].includes(o.md)?o.md:'bar';r.o=(Array.isArray(o.o)?o.o:[]).slice(0,80).filter(x=>x&&typeof x=='object'&&(x.k=='p'||x.k=='m')&&Number.isInteger(x.id)).map(x=>{let y={k:x.k,id:x.id,n:lvTx(x.n,40),st:N(x.st,0,2)||0,fx:(Array.isArray(x.fx)?x.fx:[]).slice(0,20).filter(Array.isArray).map(f=>[lvTx(f[0],30),N(f[1],0,999)||0]),dv:x.dv?1:0};if(Number.isFinite(x.i))y.i=N(x.i,-99,999);['hp','mh','tp'].forEach(k=>{if(Number.isFinite(x[k]))y[k]=N(x[k],-9999,99999)});if(Number.isFinite(x.pc))y.pc=N(x.pc,0,100);if(Number.isFinite(x.c))y.c=N(x.c,0,3);if(Array.isArray(x.ds))y.ds=[N(x.ds[0],0,3)||0,N(x.ds[1],0,3)||0];return y});r.cur=N(o.cur,-1,r.o.length-1);if(r.cur==null)r.cur=-1;return r}
function lvEnt(y,i,md){let o={k:y.k,id:y.id,n:lvTx(y.n,40),fx:(y.fx||[]).map(f=>[lvTx(f.n,30),f.t|0]),dv:y.dsv?1:0};if(i!=null)o.i=i;if(y.k=='p'){o.hp=y.hp;o.mh=y.mh;if(y.tp)o.tp=y.tp;o.st=y.dead?2:y.hp<=0?1:0;if(o.st==1)o.ds=y.ds}else{o.st=y.hp<=0?2:0;let pc=Math.max(0,Math.min(100,Math.round(100*y.hp/y.mh)));if(md=='num'){o.hp=y.hp;o.mh=y.mh}else if(md=='txt')o.c=pc>75?0:pc>40?1:pc>15?2:3;else o.pc=pc}return o}
function lvSnap(){let d=DD(),e=d.en,md=(d.lv&&d.lv.mode)||'bar',pl=d.pt.map(p=>({id:p.id,n:lvTx(p.n,40)})),fin=d.pt.filter(p=>p.lvp&&d.lv&&d.lv.rw&&d.lv.rw[p.lvp]&&d.lv.rw[p.lvp].fin==1).map(p=>p.lvp);if(!e||e.ph=='s')return{v:1,ph:'s',pl,fin};if(e.ph!='r')return{v:1,ph:'f',pl,fin};let o=e.tl.map(q=>{let y=ent(q.k,q.id);return y?lvEnt(y,q.i,md):null}).filter(Boolean);d.pt.forEach(p=>{if(!e.tl.some(q=>q.k=='p'&&q.id==p.id))o.push(lvEnt(p,null,md))});let cu=e.tl[e.cur],ci=cu?o.findIndex(x=>x.k==cu.k&&x.id==cu.id):-1;return{v:1,ph:'r',rnd:e.rnd,cur:ci,o,pl,md,fin}}
