function lvAccGc(){let d=DD(),l=d.lv,ch=0;if(!l||!l.acc||!LV.mq||!LV.mq.on)return;Object.keys(l.acc).forEach(pid=>{let p=d.pt.find(x=>x.lvp==pid);if(p){if(l.acc[pid]!==p.id){l.acc[pid]=p.id;ch=1;lvAnswer(pid,1,p.id)}return}let gp=LV.gp=LV.gp||{};if(!gp[pid]){gp[pid]=1;lvEncM({t:'gone',pid,ts:Date.now()}).then(u=>{if(LV.mq&&LV.mq.on&&LV.mq.pub(LV.base+'/a/'+pid,u,1)&&l.acc[pid]!=null&&!d.pt.some(x=>x.lvp==pid)){delete l.acc[pid];sv()}}).finally(()=>{delete gp[pid]})}});if(ch)sv()}
