async function lvStartM(){if(!(typeof crypto!='undefined'&&crypto.subtle)){LV.msg='Il collegamento live richiede una pagina sicura (HTTPS).';return lvRefresh()}let d=DD();if(!d.lv||!d.lv.room)d.lv=Object.assign(d.lv||{mode:'bar'},{room:lvRnd(16),ks:lvRnd(32)});d.lv.on=1;LV.m=1;LV.v=0;LV.profs={};LV.rolls=[];sv();await lvMK();let ok=await lvOpen('m',d.lv.room,d.lv.ks);R();return ok}
