async function lvMsg(tp,pl){if(LV.m){let k=tp.split('/'),ty=k[k.length-2],pid=k[k.length-1];if(!/^[0-9a-f]{8}$/.test(pid))return;if(ty=='q'&&pl.length>450000)return;let o=await lvDec(pl);if(!o||typeof o!='object'||o.pid!==pid)return;if(ty=='p')lvProf(o);else if(ty=='d')lvRoll(o);else if(ty=='q')lvSheetReq(o)}else{let pid=(S.lvj||{}).pid;if(tp==LV.base+'/s'){if(!pl.length)return;let o=lvSnapClean(await lvTrust(await lvDecT(pl)));if(!o)return;if(o.ts&&LV.snapTs&&o.ts<LV.snapTs)return;if(o.ts)LV.snapTs=o.ts;if(o.ph=='x'){LV.snap=null;LV.at=Date.now();return lvRefresh()}LV.snap=o;LV.at=Date.now();lvRelock(o);lvAutoUnlock(o);lvStale(o);lvSyncHp(o);lvRound(o);lvRefresh()}else if(tp==LV.base+'/a/'+pid){if(!pl.length)return;let o=await lvTrust(await lvDecT(pl)),j=S.lvj;if(!o||typeof o!='object'||o.pid!==pid)return;if(Number.isFinite(o.ts)){if(j.lt&&o.ts<=j.lt)return;j.lt=o.ts}if(o.t=='gone')return lvGone('Il Master ti ha tolto dallo scontro.');lvOnAcc(o)}else if(tp==LV.base+'/w/'+pid){let o=pl.length&&await lvTrust(await lvDecT(pl));if(o)lvOnRew(o)}}}
function lvPid(pid,me){let d=DD(),p=d.pt.find(x=>x.lvp==pid&&d.lv&&d.lv.acc&&d.lv.acc[pid]==x.id);return p?p.id:Number.isInteger(me)?me:null}
function lvProf(o){if(o.t!='prof')return;if(!LV.profs[o.pid]&&Object.keys(LV.profs).length>=24)return;let me=lvPid(o.pid,o.me);if(me!=null&&me!==o.me&&(DD().lv||{}).acc&&DD().lv.acc[o.pid]===me)lvAnswer(o.pid,1,me);LV.profs[o.pid]={pid:o.pid,me,n:lvTx(o.n,40),tr:lvTr(o.tr),t:Date.now()};lvRefresh()}
function lvRoll(o){if(o.t!='roll'||!LVKD.includes(o.kind)||!LVD.includes(o.die)||!Array.isArray(o.r)||o.r.length<1||o.r.length>20||o.r.some(v=>!Number.isInteger(v)||v<1||v>o.die)||!Number.isInteger(o.mod)||Math.abs(o.mod)>100||!Number.isInteger(o.tot)||Math.abs(o.tot)>2000||!Number.isInteger(o.d))return;let now=Date.now(),q=(LV.rl[o.pid]=(LV.rl[o.pid]||[]).filter(t=>now-t<2000));if(q.length>=6)return;q.push(now);if(LV.rolls.some(x=>x.pid==o.pid&&x.ts==o.ts))return;let me=lvPid(o.pid,o.me);LV.rolls.unshift({pid:o.pid,me,n:lvTx(o.n,40),kind:o.kind,no:o.no==1?1:0,lab:lvTx(o.lab,60),die:o.die,r:o.r.slice(),mod:o.mod,tot:o.tot,d:o.d,adv:o.adv==1||o.adv==-1?o.adv:0,ts:Number.isInteger(o.ts)?o.ts:now,at:now});LV.rolls.length=Math.min(LV.rolls.length,30);if(o.kind=='init'){let dd=DD(),pp=dd.pt.find(x=>x.id==me&&x.lvp==o.pid);if(pp&&pp.ini==null&&!(dd.en&&dd.en.ph!='s')){pp.ini=o.tot;sv();R()}}LV.open=1;try{navigator.vibrate&&navigator.vibrate(60)}catch(e){}lvRefresh()}
