function lvUse(i){let r=LV.rolls[i];if(!r)return;let id=null,v=r.d,tot=0;if(r.kind=='ts'){let rr=(DD().en&&DD().en.ui&&DD().en.ui.r)||{},c=[['tsr',rr.ts],['tse',rr.ets]].filter(x=>$(x[0]));id=(c.find(x=>x[1]&&r.lab.includes(x[1]))||c[0]||[])[0];v=r.tot;tot=1}else if(r.kind=='death')id=$('dsm')?'dsm':null;else if(r.kind=='dmg'||r.kind=='item'){id=$('am')?'am':$('fdm')?'fdm':null;v=r.tot}if(!id)return T('Ora non c\'è nessun campo dove inserire questo valore.');$(id).value=v;let cb=$(id+'t');if(cb)cb.checked=!!tot;T('<b>'+sxE(lvWho(r))+'</b><div class="big">'+v+'</div><small>'+(tot?'totale già con il bonus: ora premi Applica':'inserito nel campo: ora premi Applica o Conferma')+'</small>')}
