function lvPm(){let d=DD(),h=`<small class="mu">${LV.m?'Stato: '+lvStTx()+(LV.url?' ('+sxE(LV.url.replace(/^wss:\/\//,'').split('/')[0])+')':''):'Spento'}</small>`;if(!LV.m)return h+`<p class="mu">Avvia la condivisione per far vedere ai giocatori, in tempo reale e in sola lettura, turni, PF ed effetti. Solo tu controlli il combattimento.</p><button class="b" onclick="lvStartM()">Avvia la condivisione live</button>${LV.msg?'<p class="mu">'+sxE(LV.msg)+'</p>':''}`;let lk=lvLink(),cd=lvCode(),pr=Object.values(LV.profs),act=pr.filter(p=>Date.now()-p.t<6e5).length;h+=` - ${pr.length} giocator${pr.length==1?'e':'i'} collegat${pr.length==1?'o':'i'}`;h+=`<label>Link per i giocatori<input readonly value="${sxE(lk)}" onclick="this.select()"></label><div class="r"><button class="chip" onclick="lvCopy(lvLink())">Copia link</button><button class="chip" onclick="lvShare()">Condividi</button><button class="chip" onclick="lvCopy(lvCode())">Copia codice</button></div>${/^https:/.test(location.href)?'':'<small class="mu">Questo indirizzo non è online: i giocatori useranno il codice da "Unisciti" quando l\'app sarà su GitHub Pages.</small>'}<label>PF dei mostri<select onchange="lvMode(this.value)">${[['bar','Solo barra'],['num','Numeri esatti'],['txt','Solo stato (illeso, ferito...)']].map(a=>`<option value="${a[0]}" ${((d.lv&&d.lv.mode)||'bar')==a[0]?'selected':''}>${a[1]}</option>`).join('')}</select></label><div class="r" style="margin-top:6px"><button class="chip" onclick="lvNew()">Nuovo link</button><button class="chip" onclick="lvStopM()">Ferma</button></div>${LV.msg?'<p class="mu">'+sxE(LV.msg)+'</p>':''}`;
let rq=Object.values(LV.req);h+=`<p style="margin:10px 0 2px"><b>Richieste di ingresso</b></p>`+(rq.length?rq.map(q=>`<div class="c"><b>${sxE(q.n)}</b>${q.er?`<br><small class="mu">Non importabile: ${sxE(q.er)}</small>`:lvReqInfo(q)}<div class="r" style="margin-top:6px">${q.er?'':`<button class="chip" onclick="lvAccept('${jsA(q.pid)}')">Accetta</button>`}<button class="chip" onclick="lvReject('${jsA(q.pid)}')">${q.er?'Elimina':'Rifiuta'}</button></div></div>`).join(''):'<small class="mu">Nessuna richiesta: i giocatori inviano la scheda quando entrano.</small>');let rl=LV.rolls.slice(0,8);h+=`<p style="margin:10px 0 2px"><b>Tiri dei giocatori</b></p>${rl.length?rl.map((r,i)=>`<div class="row" style="cursor:default"><span>${sxE(lvWho(r))} - ${sxE(r.lab)}${r.no?'':': <b>'+r.tot+'</b>'}<br><small class="mu">${r.no?'oggetto usato':'d'+r.die+' ['+r.r.join(', ')+']'}${r.mod&&!r.no?' '+sg(r.mod):''}${r.adv?(r.adv>0?' vantaggio':' svantaggio'):''} - ${Math.max(0,Math.round((Date.now()-r.at)/1000))} s fa</small></span>${['ts','death','dmg','item'].includes(r.kind)&&!r.no?`<button class="chip" onclick="lvUse(${i})">Usa</button>`:''}</div>`).join(''):'<small class="mu">Nessun tiro ricevuto.</small>'}`;
let pp=pr.filter(p=>!lvEmpty(p.tr)&&JSON.stringify(p.tr)!=JSON.stringify(lvTr((d.pt.find(x=>x.id==p.me)||{}).tr)));if(pp.length)h+=`<p style="margin:10px 0 2px"><b>Difese proposte</b></p>`+pp.map(p=>`<div class="c"><b>${sxE(((d.pt.find(x=>x.id==p.me)||{}).n)||p.n)}</b>: ${sxE(lvTrTx(p.tr))}<div class="r" style="margin-top:6px"><button class="chip" onclick="lvApply('${jsA(p.pid)}')">Applica</button><button class="chip" onclick="lvIgnore('${jsA(p.pid)}')">Ignora</button></div></div>`).join('');
h+=`<p style="margin:10px 0 2px"><b>Difese dei giocatori</b></p>`+(d.pt.length?d.pt.map(p=>`<div class="row" style="cursor:default"><span>${sxE(p.n)}<br><small class="mu">${sxE(lvTrTx(lvTr(p.tr)))}</small></span><button class="chip" onclick="lvTrM(${p.id})">Modifica</button>${p.lvp&&!(d.lv&&d.lv.rw&&d.lv.rw[p.lvp]&&d.lv.rw[p.lvp].fin==1)?'<button class="chip" onclick="lvUnlockP(\''+p.lvp+'\')">Sblocca</button>':''}</div>`).join('')+'<div class="r" style="margin-top:6px"><button class="chip" onclick="lvUnlockAll()">Sblocca tutte le schede</button></div>':'<small class="mu">Nessun giocatore nello scontro.</small>');return h}
