function spE(i){let s=C().sp[i];if(!s)return;let ef=Array.isArray(s.ef)?s.ef.join(', '):(s.ef||'');MO(`<h3>Modifica ${s.l?'incantesimo':'trucchetto'}</h3><label>Nome<input id="e_n" value="${sxE(s.n)}"></label><label>Livello (0 = trucchetto)<input id="e_l" type="number" value="${s.l|0}" min="0" max="9"></label><label>Tempo di lancio<input id="e_t" value="${sxE(s.t||'')}"></label><label>Gittata<input id="e_r" value="${sxE(s.r||'')}"></label><label>Componenti e materiali (es. V, S, M (polvere))<input id="e_c" value="${sxE(s.c&&s.c!='-'?s.c:'')}"></label><label>Durata<input id="e_d" value="${sxE(s.d||'')}"></label><div class="r"><label><input type="checkbox" id="e_cn" ${s.cn?'checked':''}> Concentrazione</label><label><input type="checkbox" id="e_ri" ${s.ri?'checked':''}> Rituale</label></div><label>Danno o cura (es. 2d6 fuoco)<input id="e_m" value="${sxE(s.dm||'')}"></label><label>Dettagli rituale<input id="e_rt" value="${sxE(s.rt||'')}"></label><label>Effetti di stato (separati da virgola)<input id="e_ef" value="${sxE(ef)}"></label><label>Note<input id="e_no" value="${sxE(s.no||'')}"></label><div class="r" style="margin-top:10px"><button class="b" onclick="spES(${i})">Salva</button><button class="b o" onclick="closeM()">Annulla</button><button class="b d" style="margin-left:auto" onclick="spDel(${i})">Elimina</button></div>`)}
function spDel(i){let s=C().sp[i];if(!s||typeof confirm=='function'&&!confirm('Eliminare '+s.n+'?'))return;C().sp.splice(i,1);closeM();sv();R()}
function spES(i){let s=C().sp[i];if(!s)return;let dm=($('e_m').value||'').trim();if(dm&&dm!=(s.dm||'')&&!parse(dm))return T('Danno o cura non valido: scrivi per esempio 2d6 fuoco');Object.assign(s,{n:($('e_n').value||'').trim()||s.n,l:Math.max(0,Math.min(9,+$('e_l').value||0)),t:$('e_t').value,r:$('e_r').value||'-',c:$('e_c').value||'-',d:$('e_d').value,cn:$('e_cn').checked?1:0,ri:$('e_ri').checked?1:0,dm,no:$('e_no').value,rt:$('e_rt').value,ef:$('e_ef').value});closeM();sv();R()}
function tmTickC(c,n){if(!c)return;tmMig(c);n=n||1;let t=c.tm||[],msg=[];for(let i=0;i<n;i++)t.forEach(x=>{if(x.done)return;if(x.k=='ira'){let per=c.lv>=15&&c.c==0;if(!per&&!x.ex){x.done=1;msg.push('Ira terminata: non è stata prolungata');return}x.ex=0}x.r--;if(x.r<=0){x.done=1;msg.push(x.n+' terminata')}});if(t.some(x=>x.done&&x.k=='ira'))c.ira=0;c.tm=t.filter(x=>!x.done);sv();R();if(msg.length)T('<b>'+msg.join('<br>')+'</b>')}
function tmTick(n){tmTickC(C(),n)}
function tmEndFight(c){let t=c.tm||[],was=c.ira||t.some(x=>x.k=='ira');c.tm=t.filter(x=>x.k!='ira');c.ira=0;if(was){sv();R();T('<b>Combattimento finito: Ira terminata</b>')}}
function tmExtAuto(){let c=C(),t=c&&c.tm&&c.tm.find(x=>x.k=='ira');if(t&&!t.ex){t.ex=1;sv();setTimeout(()=>R(),60)}}
function lvRound(o){if(!o)return;let a=S.lvj&&S.lvj.acc,c=a&&S.chs[a.ci];if(o.ph=='r'&&Number.isFinite(o.rnd)){if(LV.rd==null||o.rnd<LV.rd){LV.rd=o.rnd;return}if(o.rnd>LV.rd){let n=o.rnd-LV.rd;LV.rd=o.rnd;if(c&&!a.fin)tmTickC(c,n)}}else if(LV.rd!=null){LV.rd=null;if(c)tmEndFight(c)}}
function lvTmRage(){let c=C();if(!c||c.c!=0||c.ira)return;let mx=ragU(c.lv),u=c.ru||0;if(u>=mx)return T('Nessuna Ira disponibile: si recupera con il riposo lungo');c.ru=u+1;c.ira=1;c.tm=TMS().filter(x=>x.k!='ira').concat([{k:'ira',n:'Ira',r:10,m:10,ex:1}]);sv();R();T('<b>Ira attivata</b><small>Usi rimasti: '+(mx-c.ru)+'/'+mx+'</small>')}
