function lvTmAddM(){MO(`<h3>Nuova durata</h3><label>Nome abilità<input id="tn_n" placeholder="es. Forma selvatica"></label><div class="r"><input id="tn_v" type="number" min="1" value="1" style="flex:1"><select id="tn_u" style="flex:1"><option value="1">minuti (round)</option><option value="60">ore</option></select></div><small class="mu">1 minuto = 1 round. Il conto scende di un round a ogni round del combattimento.</small><div class="r" style="margin-top:10px"><button class="b" onclick="lvTmAdd()">Avvia</button><button class="b o" onclick="closeM()">Annulla</button></div>`)}
function lvTmAdd(){let n=($('tn_n').value||'').trim(),v=Math.max(1,Math.floor(+$('tn_v').value||0)),r=Math.min(1440,v*(+$('tn_u').value||1));if(!n)return T("Scrivi il nome dell'abilità");TMS().push({k:'c'+Date.now().toString(36),n,r,m:r});closeM();sv();R()}
function lvTmInnate(){let c=C();if(!isSorc(c)||TMS().some(x=>x.k=='mi'))return;let u=c.iu||0;if(u>=2){if(c.lv<7)return T('Magia innata esaurita: si recupera con il riposo lungo');if(spLeft()<2)return T('Magia innata esaurita e non hai 2 Punti Stregoneria');if(typeof confirm=='function'&&!confirm('Usi finiti: spendere 2 Punti Stregoneria per attivare la Magia innata?'))return;c.pu=(c.pu||0)+2}else c.iu=u+1;TMS().push({k:'mi',n:'Magia innata',r:1,m:1});sv();R();T('<b>Magia innata attiva</b><small>1 minuto (1 round): CD +1 agli incantesimi da Stregone e vantaggio ai loro tiri per colpire</small>')}
function lvMm(k){let c=C(),m=MMG[k];if(!m||!(c.mm||[]).includes(m[0]))return;if(spLeft()<m[1])return T('Punti Stregoneria insufficienti (servono '+m[1]+')');c.pu=(c.pu||0)+m[1];sv();R();T('<b>'+m[0]+'</b><small>-'+m[1]+' PS - restano '+spLeft()+'/'+spMax(c.lv)+'</small><p><small>'+m[2]+'</small></p>')}
