function spSlotToPs(){let c=C(),l=+$('fm_l').value,sl=slots();if(!(sl[l-1]>(c.us[l]||0)))return T('Nessuno slot disponibile di livello '+l);let g=Math.min(l,spMax(c.lv)-spLeft());if(g<=0)return T('Hai già tutti i Punti Stregoneria');c.us[l]=(c.us[l]||0)+1;c.pu=Math.max(0,(c.pu||0)-l);sv();R();T('<b>+'+g+' PS</b><small>Slot di livello '+l+' speso</small>')}
function spPsToSlot(){let c=C(),l=+$('fm_l').value,co={1:2,2:3,3:5,4:6,5:7}[l];if(!co)return T('Puoi creare solo slot dal livello 1 al 5');if(spLeft()<co)return T('Servono '+co+' Punti Stregoneria');if(!(c.us[l]>0))return T('Non hai slot spesi di livello '+l+' da recuperare');c.pu=(c.pu||0)+co;c.us[l]--;sv();R();T('<b>Slot di livello '+l+' creato</b><small>-'+co+' PS</small>')}
function mmM(){let c=C();if(!isSorc(c))return;let n=mmN(c.lv);if(!n)return T('Le Metamagie arrivano al livello 2 (Fonte di magia)');let k=c.mm||[];MO(`<h3>Metamagie (${n})</h3><p class="mu">Scegline fino a ${n}. Ne ottieni altre due ai livelli 10 e 17.</p>${MMG.map((m,i)=>`<label style="display:flex;gap:8px;align-items:flex-start;margin:6px 0"><input type="checkbox" class="mmc" value="${i}" style="width:auto;margin-top:4px" ${k.includes(m[0])?'checked':''}><span><b>${m[0]}</b> (${m[1]} PS)<br><small class="mu">${m[2]}</small></span></label>`).join('')}<div class="r" style="margin-top:10px"><button class="b" onclick="mmS()">Salva</button><button class="b o" onclick="closeM()">Annulla</button></div>`)}
