function rageCard(){let c=C(),mx=ragU(c.lv),u=Math.min(mx,c.ru||0),t=TMS().find(x=>x.k=='ira'),per=c.lv>=15,rg=c.lv<9?2:c.lv<16?3:4;return `<div class="c"><div class="r" style="justify-content:space-between"><b>Ira</b><span>Usi <b>${mx-u}</b>/${mx} - danni +${rg}</span></div>`+(c.ira?`<div class="tm"><b>Ira attiva</b>`+(t?`<div>${tmFmt(t.r)} al massimo</div><div class="bar"><i style="width:${Math.max(0,Math.round(100*t.r/t.m))}%"></i></div>`+(per?`<small class="mu">Ira persistente: dura tutti i 10 minuti senza prolungarla.</small>`:`<div>${t.ex?'Prolungata: continua al prossimo round':"<b>Da prolungare</b> entro fine turno: attacca un nemico, imponi un TS o usa l'azione bonus"}</div>`):'<small class="mu">Attiva senza timer</small>')+`<div class="r" style="margin-top:6px">${t&&!per?`<button class="b" onclick="lvTmExt()">Prolunga (azione bonus)</button>`:''}<button class="b o" onclick="lvTmEnd('ira')">Termina Ira</button></div></div>`:`<div class="r" style="margin-top:6px"><button class="b" onclick="lvTmRage()" ${u>=mx?'disabled':''}>Entra in Ira</button><small class="mu">${u>=mx?'Usi finiti: si recuperano con il riposo lungo':'Consuma un uso. Durata massima 10 minuti.'}</small></div>`)+`<small class="mu">Con l'Ira attiva il bonus ai danni si aggiunge da solo ai colpi in mischia.</small></div>`}
function tmCard(){let c=C(),t=TMS().filter(x=>x.k!='ira'),live=!!LV.v;return `<div class="c"><div class="r" style="justify-content:space-between"><b>Durate</b><span class="r"><button class="chip" onclick="lvTmAddM()">+ Timer</button>${!live&&(t.length||c.ira)?`<button class="chip" onclick="tmTick(1)">Round successivo</button>`:''}</span></div>${t.length?t.map(x=>`<div style="margin-top:8px"><div class="r" style="justify-content:space-between"><span><b>${sxE(x.n)}</b> - ${tmFmt(x.r)}</span><button class="chip" onclick="lvTmEnd('${jsA(x.k)}')">Termina</button></div><div class="bar"><i style="width:${Math.max(0,Math.round(100*x.r/x.m))}%"></i></div></div>`).join(''):'<small class="mu">Nessuna durata attiva. Il conto scende di un round a ogni round del combattimento live.</small>'}</div>`}
function sorcCard(){let c=C();if(!isSorc(c))return'';let mx=spMax(c.lv),left=spLeft(),n=mmN(c.lv),mm=c.mm||[],sl=slots(),iu=c.iu||0,mi=TMS().some(x=>x.k=='mi');let h=`<div class="c"><div class="r" style="justify-content:space-between"><b>Punti Stregoneria</b><span><b>${left}</b> / ${mx}</span></div>`;if(!mx)h+='<small class="mu">I Punti Stregoneria arrivano al livello 2 con Fonte di magia.</small>';else{h+=`<div style="margin-top:6px">${Array.from({length:mx},(_,j)=>`<span class="pip ${j<left?'f':''}"></span>`).join('')}</div><div class="r" style="margin-top:6px"><button class="chip" onclick="spAdj(-1)">-1</button><button class="chip" onclick="spAdj(1)">+1</button></div>`}h+=`<div class="r" style="margin-top:8px"><button class="b" onclick="lvTmInnate()" ${mi?'disabled':''}>Magia innata</button><small class="mu">Usi ${Math.max(0,2-iu)}/2${c.lv>=7?' (a 0 puoi spendere 2 PS)':''}. 1 minuto: CD +1 e vantaggio ai tiri per colpire con incantesimi da Stregone.</small></div>`;if(mx){h+=`<div class="r" style="margin-top:8px"><select id="fm_l" style="flex:1">${sl.map((q,i)=>q?`<option value="${i+1}">Slot livello ${i+1}</option>`:'').join('')}</select><button class="chip" onclick="spSlotToPs()">Slot → PS</button><button class="chip" onclick="spPsToSlot()">PS → slot</button></div><small class="mu">Fonte di magia: PS → slot recupera uno slot speso (costo 2, 3, 5, 6, 7 per i livelli 1-5).</small>`}h+=`<div class="r" style="justify-content:space-between;margin-top:10px"><b>Metamagia</b><span><small>${mm.length}/${n} conosciute</small> <button class="chip" onclick="mmM()">Scegli</button></span></div>`;if(!n)h+='<small class="mu">La Metamagia arriva al livello 2.</small>';else if(!mm.length)h+='<small class="mu">Scegli le tue Metamagie con il tasto Scegli.</small>';h+=MMG.map((m,i)=>mm.includes(m[0])?`<div style="margin-top:8px"><div class="r" style="justify-content:space-between"><b>${m[0]}</b><button class="b" onclick="lvMm(${i})" ${left<m[1]?'disabled':''}>Usa (${m[1]} PS)</button></div><small class="mu">${m[2]}</small></div>`:'').join('');h+=`<details style="margin-top:8px"><summary>Tutte le opzioni di Metamagia</summary>${MMG.map(m=>`<p><b>${m[0]}</b> (${m[1]} PS)${mm.includes(m[0])?' - conosciuta':''}<br><small class="mu">${m[2]}</small></p>`).join('')}</details></div>`;return h}
